#!/bin/sh
# Deja la demo en su estado inicial: hitos m2, m3, m5 y m6 pendientes, sin eventos ni facturas nuevas, las lecturas de telemetría que llegaron por la API de ingesta o el simulador (id > 4200; las 4.200 del Excel no se tocan) y solo los 4 usuarios de demostración con su rol, en español y con el tema «system».
# Solo toca los datos de DEMOSTRACIÓN. Usa el superusuario de PostgreSQL del contenedor local.
set -e
cd "$(dirname "$0")/.."
. ./.env
psqlc() { docker compose exec -T -e PGPASSWORD="$POSTGRES_ADMIN_PASSWORD" postgres psql -h localhost -U "$POSTGRES_ADMIN_USER" -d "$1" -Atc "$2" >/dev/null; }
psqlc projects "DELETE FROM milestones WHERE id LIKE 'm-%'; DELETE FROM projects WHERE id LIKE 'p-%'; UPDATE milestones SET status='pending', approved_at=NULL, approved_by=NULL WHERE id IN ('m2','m3','m5','m6'); DELETE FROM outbox_events;"
psqlc identity "DELETE FROM refresh_tokens; DELETE FROM users WHERE email NOT IN ('laura.rios@nexus.example','andres.mora@nexus.example','camila.soto@nexus.example','diana.vega@nexus.example'); UPDATE users SET role='project_lead', language='es', theme='system' WHERE email='laura.rios@nexus.example'; UPDATE users SET role='billing_analyst', language='es', theme='system' WHERE email='andres.mora@nexus.example'; UPDATE users SET role='sales', language='es', theme='system' WHERE email='camila.soto@nexus.example'; UPDATE users SET role='manager', language='es', theme='system' WHERE email='diana.vega@nexus.example';"
# Los documentos electrónicos no se pueden borrar (la base lo impide); el reinicio de la demo lo declara a propósito, solo en esta sesión.
psqlc billing "SET erp.allow_einvoice_delete = on; DELETE FROM einvoice_deliveries; DELETE FROM electronic_invoices; UPDATE einvoice_numbering SET next_number = range_from WHERE id = 1; DELETE FROM customers; INSERT INTO customers (id, key, name, nit, dv, email, address, city) VALUES (gen_random_uuid(), 'banco andino (example)', 'Banco Andino (example)', '900000001', 2, 'cuentas@banco-andino.example', 'Carrera 7 # 71-21', 'Bogotá'), (gen_random_uuid(), 'retail norte (example)', 'Retail Norte (example)', '900000002', 1, 'facturas@retail-norte.example', 'Calle 10 # 4-33', 'Barranquilla'), (gen_random_uuid(), 'pyme sur (example)', 'Pyme Sur (example)', '900000003', 7, 'contabilidad@pyme-sur.example', 'Avenida 5N # 23-40', 'Cali'); UPDATE invoices SET issued_at = created_at, due_date = created_at + interval '30 days' WHERE number IN ('INV-0101','INV-0102'); UPDATE invoices SET client_name = CASE number WHEN 'INV-0101' THEN 'Banco Andino (example)' ELSE 'Retail Norte (example)' END WHERE number IN ('INV-0101','INV-0102'); DELETE FROM invoices WHERE number NOT IN ('INV-0101','INV-0102'); DELETE FROM processed_events; DELETE FROM outbox_events; SELECT setval('invoice_number_seq', 103, false);"
psqlc analytics "UPDATE milestone_facts SET overdue_at = NULL, overdue_days = NULL; DELETE FROM milestone_facts WHERE milestone_id NOT IN ('m1','m2','m3','m4','m5','m6'); INSERT INTO milestone_facts (milestone_id, project_id, project_name, milestone_name, amount_cop, created_at) VALUES ('m2','p1','Branch network upgrade','Link redundancy design',18500000,'2026-10-01T12:00:00Z'), ('m3','p1','Branch network upgrade','Cutover',25000000,'2026-10-01T12:00:00Z'), ('m5','p2','Retail POS integration','Pilot in 3 stores',14200000,'2026-10-01T12:00:00Z'), ('m6','p3','SME cloud migration','Inventory of workloads',7500000,'2026-10-01T12:00:00Z') ON CONFLICT (milestone_id) DO UPDATE SET project_id=EXCLUDED.project_id, project_name=EXCLUDED.project_name, milestone_name=EXCLUDED.milestone_name, amount_cop=EXCLUDED.amount_cop, created_at=EXCLUDED.created_at, approved_by=NULL, approved_at=NULL, invoice_number=NULL, invoice_status=NULL, tax_cop=NULL, total_cop=NULL, drafted_at=NULL, issued_at=NULL; DELETE FROM processed_events; DELETE FROM activity_entries;"
psqlc operations "DELETE FROM iot_readings WHERE id > 4200;"
psqlc notifications "DELETE FROM notification_reads; DELETE FROM notifications; DELETE FROM processed_events;"
psqlc capacity "DELETE FROM outbox_events; DELETE FROM allocations; DELETE FROM engineers WHERE id::text NOT LIKE '11111111-%'; INSERT INTO allocations (engineer_id, project_name, percent, start_date, end_date) SELECT e.id, v.p, v.pc, current_date + v.s, current_date + v.e FROM (VALUES ('11111111-1111-4111-8111-111111111101'::uuid,'Branch network upgrade',60,-10,40),('11111111-1111-4111-8111-111111111101','Retail POS integration',30,5,30),('11111111-1111-4111-8111-111111111102','SME cloud migration',80,-5,60),('11111111-1111-4111-8111-111111111103','Branch network upgrade',40,-3,25),('11111111-1111-4111-8111-111111111104','Retail POS integration',50,-20,15),('11111111-1111-4111-8111-111111111104','SME cloud migration',50,-2,20),('11111111-1111-4111-8111-111111111106','SME cloud migration',25,0,45)) AS v(id,p,pc,s,e) JOIN engineers e ON e.id = v.id;"
echo "Demo reiniciada: 4 hitos pendientes (m2, m3, m5, m6) y 2 facturas emitidas (INV-0101, INV-0102)."
